"/us/en/about/news/2026/stryker-expands-mako-robotics-portfolio": {"template":"news-detail","metadata":{"title":"Stryker expands Mako robotics portfolio with full market release of Mako RPS","pageTitle":null,"description":"New handheld robotic technology expands the Mako platform and brings robotic-assisted knee replacement to a new segment of the orthopaedic market.","image":"/content/dam/stryker/about/news/2026/stryker-introduces-mako-handheld-robotics/mako-rps-thumbnail.png","imageAlt":"Mako RPS","tags":["stryker:content-type/news","stryker:content-type/news/in-the-news","stryker:content-type/corporatenews"],"originallyPublished":"2026-07-16T13:07:00.000Z","lastPublished":"2026-07-16T13:07:00.000Z","contentID":"JR-GSNPS-PRESS-3660552"},"anchors":[],"disclaimer":"<p>References:</p>\r\n<ol>\r\n<li>American Joint Replacement Registry (AJRR): 2025 Annual Report. Rosemont, IL: American Academy of Orthopaedic Surgeons (AAOS), 2025.</li>\r\n<li>Australian Orthopaedic Association National Joint Replacement Registry (AOANJRR). Hip, Knee &amp; Shoulder Arthroplasty Annual Report 2025. AOA;2025. https://aoanjrr.sahmri.com/. Accessed 11 Oct. 2025</li>\r\n<li>Scott CEH, Snowden GT, Cawley W, et al. Fifteen-year prospective longitudinal cohort study of outcomes following single radius total knee arthroplasty. Bone Jt Open. 2023;4(10):808-816. Published 2023 Oct 24.doi:10.1302/2633-1462.410.BJO-2023-0086.R1</li>\r\n</ol>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/about/news/2026/stryker-introduces-first-of-its-kind-fda-authorized-surgical-application-for-apple-vision-pro-with-hip-arthroscopy-case": {"template":"news-detail","metadata":{"title":"Stryker introduces first of its kind FDA-authorized surgical application for Apple Vision Pro with hip arthroscopy case at nationally recognized academic medical center","pageTitle":null,"description":"Stryker announced today that the first surgical procedure using SportSuite Vision on Apple Vision Pro was successfully completed at Duke Health.","image":"/content/dam/stryker/about/news/2026/stryker-introduces-first-of-its-kind-fda-authorized-surgical-application-for-apple-vision-pro-with-hip-arthroscopy-case-at-nationally-recognized-academic-medical-cente/images/ssv_press-release-thumbnail.jpg","imageAlt":"ssv_press-release-thumbnail","tags":["stryker:content-type/news","stryker:content-type/news/in-the-news","stryker:content-type/corporatenews"],"originallyPublished":"2026-09-01T13:07:00.000Z","lastPublished":"2026-09-01T19:21:02.000Z","contentID":"SM-SS_VISION-PRESS-3838300"},"anchors":[],"disclaimer":"<p>SportSuite Vision Software is indicated for the intraoperative display of arthroscopic video and medical imaging during femoroacetabular impingement and labral repair hip arthroscopy procedures, and the display of the same information as presented by the HipCheck software and HipMap FAI Analysis. When using the device, surgical tasks are performed through a video see-through augmented reality head mounted display. Virtual images from video see-through augmented reality shall be used by the surgeon in conjunction with the use of traditional monitors by other operating room staff.</p>\r\n<p>*Stryker consultant</p>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/about/news/2026/stryker-introduces-mako-handheld-robotics-mako-rps": {"template":"news-detail","metadata":{"title":"Stryker introduces Mako Handheld Robotics with the limited market release of Mako RPS","pageTitle":null,"description":"Stryker announced the limited market release of Mako RPS (Robotic Power System) for Total Knee, an intuitive handheld robotic system that combines Stryker’s proven robotics and power tool legacies and represents Mako’s expansion into a new robotics platform.","image":"/content/dam/stryker/about/news/2026/stryker-introduces-mako-handheld-robotics/mako-rps-thumbnail.png","imageAlt":"Mako RPS","tags":["stryker:content-type/news","stryker:content-type/news/in-the-news","stryker:content-type/corporatenews"],"originallyPublished":"2026-02-09T15:36:51.000Z","lastPublished":"2026-02-09T15:36:51.000Z","contentID":"JR-MKOSYM-PRESS-2964050"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
