"/us/en/emergency-care/news/video/survivor-andy-hannan": {"template":"news-detail","metadata":{"title":"Survivor: Andy Hannan","pageTitle":"Survivor: Andy Hannan","description":"Andy Hannan was playing walking football when he collapsed on the field from a sudden cardiac arrest. Thankfully, one of his co-players, Sue, a first aid volunteer, immediately sprang to action. Watch how she saved his life with the help of the system of care.","image":"/content/dam/stryker/ems/videos/stories/thumbnails/andy-hannan.png","imageAlt":"Andy Hannan","tags":["stryker:business-unit/ems/news/survivor-stories","stryker:content-type/news","stryker:business-unit/ems/news/videos"],"originallyPublished":null,"lastPublished":"2024-01-25T23:02:45.000Z","contentID":null},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[{"component":"customizable_copy_co","title":"Related","items":[{"path":"/us/en/emergency-care/community-public-safety","resolved":true,"title":"Workplace and public safety","description":"An AED program is a critical link in the chain of survival of a sudden cardiac arrest, empowering you to deliver lifesaving intervention before first responders arrive. With more than a million AEDs deployed globally, Stryker offers diverse options and deep expertise to help you choose the right device and cost-effectively manage your community AED program.","image":"/content/dam/stryker/ems/images/ec-aed-community-public-safety-hero_cr2-wall-unit_1200x680.jpg","alt":"Bystander grabs LIFEPAK CR2 AED from wall in an office"},{"path":"/us/en/emergency-care/news/video/survivor-denis-legault","resolved":true,"title":"Survivor: Denis Legault","description":"Quick action (and speedy driving) by paramedics helped save sudden cardiac arrest survivor Denis Legault. Two years after the event, Denis met the crew that helped save his life.","image":"/content/dam/stryker/ems/videos/stories/thumbnails/legault-egg-thumbnail.png","alt":"Denis Legault holding eggs"},{"path":"/us/en/emergency-care/news/video/survivor-derrick-mosley","resolved":true,"title":"Survivor: Derrick Mosley","description":"After going on a morning run, Derrick began to feel some chest discomfort. His wife, Melissa, a healthcare professional trained in resuscitation, quickly recognized the warning signs of a sudden cardiac arrest. Luckily, an off-duty firefighter pulled over from traffic and began assisting. Soon EMS and Fire/Rescue units arrived to apply a LUCAS.","image":"/content/dam/stryker/ems/videos/stories/thumbnails/SCA_DerrickMosley_Final.jpg","alt":"Derrick Mosley sudden cardiac arrest survivor"}]}],"missingAlt":[]},
"/us/en/emergency-care/news/video/survivor-bennett-hart": {"template":"news-detail","metadata":{"title":"Survivor: Bennett Hart","pageTitle":null,"description":"A rare genetic condition caused Bennett Hart’s heart to stop three times between the ages of 8 and 15. Watch how this determined student athlete overcomes every obstacle with the support of his friends and family.","image":"/content/dam/stryker/ems/videos/stories/thumbnails/Survivor_Bennett_Hart.jpg","imageAlt":null,"tags":["stryker:business-unit/ems/news/survivor-stories","stryker:content-type/news","stryker:business-unit/ems/news/videos"],"originallyPublished":null,"lastPublished":"2024-01-25T23:01:31.000Z","contentID":null},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[{"component":"customizable_copy_co","title":"Related","items":[{"path":"/us/en/emergency-care/community-public-safety","resolved":true,"title":"Workplace and public safety","description":"An AED program is a critical link in the chain of survival of a sudden cardiac arrest, empowering you to deliver lifesaving intervention before first responders arrive. With more than a million AEDs deployed globally, Stryker offers diverse options and deep expertise to help you choose the right device and cost-effectively manage your community AED program.","image":"/content/dam/stryker/ems/images/ec-aed-community-public-safety-hero_cr2-wall-unit_1200x680.jpg","alt":"Bystander grabs LIFEPAK CR2 AED from wall in an office"},{"path":"/us/en/emergency-care/news/video/survivor-denis-legault","resolved":true,"title":"Survivor: Denis Legault","description":"Quick action (and speedy driving) by paramedics helped save sudden cardiac arrest survivor Denis Legault. Two years after the event, Denis met the crew that helped save his life.","image":"/content/dam/stryker/ems/videos/stories/thumbnails/legault-egg-thumbnail.png","alt":"Denis Legault holding eggs"},{"path":"/us/en/emergency-care/news/video/survivor-derrick-mosley","resolved":true,"title":"Survivor: Derrick Mosley","description":"After going on a morning run, Derrick began to feel some chest discomfort. His wife, Melissa, a healthcare professional trained in resuscitation, quickly recognized the warning signs of a sudden cardiac arrest. Luckily, an off-duty firefighter pulled over from traffic and began assisting. Soon EMS and Fire/Rescue units arrived to apply a LUCAS.","image":"/content/dam/stryker/ems/videos/stories/thumbnails/SCA_DerrickMosley_Final.jpg","alt":"Derrick Mosley sudden cardiac arrest survivor"}]}],"missingAlt":[]},
