"/us/en/endoscopy/news/advancing-surgical-education-highlights-from-ispies-at-ircad": {"template":"news-detail","metadata":{"title":"Advancing Surgical Education: Highlights from iSPIES at IRCAD North America","pageTitle":null,"description":"In mid-October, Endoscopy’s Medical Education team hosted two immersive iSPIES events at IRCAD’s state-of-the-art new lab facilities in Charlotte. Throughout both programs, more than 100 healthcare professionals came together to deepen their expertise, collaborate with peers, and gain hands-on experience with key technologies across Stryker’s portfolio.","image":"/content/dam/stryker/endoscopy/news/2026/advancing-surgical-education-highlights-from-ispies-at-ircad-north-america/iSPIES-IRCAD-North-America-thumbnail.jpg","imageAlt":"iSPIES event at IRCAD North America","tags":["stryker:business-unit/endoscopy","stryker:content-type/news"],"originallyPublished":"2026-01-07T19:36:57.000Z","lastPublished":"2026-01-07T19:36:57.000Z","contentID":"ENDO-GSNPS-SYK-2727500"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/endoscopy/news/introducing-ip-bravoe-a-new-standard-in-or-integration": {"template":"news-detail","metadata":{"title":"Introducing IP BRAVoE: A New Standard in OR Integration","pageTitle":null,"description":"Designed with surgical teams, for surgical teams - Stryker’s IP BRAVoE helps simplify the OR with seamless integration, intuitive control and future-ready performance.","image":"/content/dam/stryker/endoscopy/news/2025/introducing-ip-bravoe/IP-BRAVoE.png","imageAlt":"IP BRAVoE","tags":["stryker:content-type/news","stryker:business-unit/endoscopy"],"originallyPublished":"2025-10-29T18:54:24.000Z","lastPublished":"2025-10-29T18:54:24.000Z","contentID":"ENDO-BRAVOE-COMM-2162400-EN_US"},"anchors":[],"disclaimer":"<ol>\r\n<li>1524158</li>\r\n</ol>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/endoscopy/news/stryker-advances-urology-portfolio-launch-flexible-ureteroscope": {"template":"news-detail","metadata":{"title":"Stryker Advances Urology Portfolio with Launch of Flexible Ureteroscope","pageTitle":null,"description":"Urology continues to push the limits of minimally invasive care - and Stryker is reinforcing its commitment to the specialty with new technology, expanded service capabilities and continued engagement with the urology community.","image":"/content/dam/stryker/endoscopy/news/2026/stryker-advances-urology-portfolio/F88-ureteroscope.jpg","imageAlt":"F88","tags":["stryker:content-type/news","stryker:business-unit/endoscopy"],"originallyPublished":"2026-02-25T19:42:23.000Z","lastPublished":"2026-02-25T20:59:58.000Z","contentID":"ENDO-SPYC-ARTI-2935576"},"anchors":[],"disclaimer":"<p>References</p>\r\n<ol>\r\n<li>F88 Flexible Ureteroscope design intent and durability features. <b>DFHD 17934 Rev A</b></li>\r\n<li>F88 Limited Launch surgeon survey: overall performance confidence. <b>DFHD 17934 Rev A</b></li>\r\n<li>F88 Limited Launch surgeon survey: durability confidence when visualizing difficult anatomy. <b>DFHD 17934 Rev A</b></li>\r\n<li>1000904469</li>\r\n<li>1000902089 Rev A - Stryker ProCare Customer Engagement Study. 2014 Gallup Inc. Published August 2014</li>\r\n</ol>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
