"/us/en/ent/news/Cigna-Coverage-Policy-Update-ClariFix": {"template":"news-detail","metadata":{"title":"Cigna Coverage Policy Update for ClariFix® Cryotherapy, Enhancing Patient Access for Chronic Rhinitis Treatment","pageTitle":"Cigna Coverage Policy Update for ClariFix® Cryotherapy, Enhancing Patient Access for Chronic Rhinitis Treatment","description":"Portage, Michigan, USA – July 7, 2025 – Stryker, a global leader in medical technologies,today announced that Cigna Healthcare will reclassify ClariFix® (CPT® 31243), removing it from the insurer’s experimental, investigational, and unproven procedures list, e􀆯ffective September 15, 2025. This policy update marks a significant advancement in patient access to an evidence-based treatment for chronic rhinitis.","image":null,"imageAlt":null,"tags":["stryker:content-type/news"],"originallyPublished":"2025-07-07T20:14:12.000Z","lastPublished":"2025-11-12T19:20:04.000Z","contentID":"ENT-GSNPS-SYK-2061250_REV-0"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/ent/news/new-real-world-health-economic-study-demonstrates-substantial-healthcare-savings": {"template":"news-detail","metadata":{"title":"New real-world health economic study demonstrates substantial healthcare savings with the LATERA® absorbable nasal implant system","pageTitle":null,"description":"Portage, Michigan, USA – August 23, 2024 – Stryker, a global leader in medical technologies, announced the publication of a new health economic study that has unveiled substantial potential cost savings associated with the LATERA® absorbable nasal implant system. LATERA was compared to traditional surgical repair for the treatment of nasal valve collapse (NVC). The study, which analyzed claims data from thousands of patients, demonstrates that payers could save approximately $2,200 per patient on the date of the procedure by opting for the minimally invasive LATERA approach over surgical intervention.","image":null,"imageAlt":null,"tags":["stryker:content-type/news/ent/clinical-information","stryker:content-type/news"],"originallyPublished":"2024-08-23T15:07:27.000Z","lastPublished":"2025-10-31T13:54:09.000Z","contentID":"ENT-GSNPS-PRESS-1226437_REV-0"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/ent/news/stryker-announces-creation-new-nasal-valve-collapse-1CD-10-CM-codes": {"template":"news-detail","metadata":{"title":"Stryker announces creation of new nasal valve collapse ICD-10-CM codes for accurate diagnosis reporting","pageTitle":null,"description":"Portage, Michigan, USA – October 10, 2024 – Stryker, a global leader in medical technologies, announces that the Centers for Disease Control (CDC) and Centers for Medicare and Medicaid Services (CMS) have released new diagnosis codes for nasal valve collapse (NVC), effective October 1, 2024.","image":null,"imageAlt":null,"tags":["stryker:content-type/news"],"originallyPublished":"2024-10-10T19:59:59.000Z","lastPublished":"2024-10-10T19:59:59.000Z","contentID":"ENT-GSNPS-REIM-1395800_REV-0"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/ent/news/stryker-announces-creation-of-new-category-1-cpt-codes-for-repor": {"template":"news-detail","metadata":{"title":"Stryker announces creation of new Category 1 CPT codes for reporting posterior nasal nerve ablation procedures","pageTitle":null,"description":null,"image":null,"imageAlt":null,"tags":["stryker:content-type/news","stryker:content-type/news/ent/clinical-information"],"originallyPublished":null,"lastPublished":"2023-11-08T20:41:41.000Z","contentID":null},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/ent/news/united-healthcare-medicare-advantage-policy-update-for-clarifix-": {"template":"news-detail","metadata":{"title":"United Healthcare Medicare Advantage policy update for ClariFix® cryotherapy, enhancing patient access for chronic rhinitis treatment","pageTitle":"United Healthcare Medicare Advantage policy update ","description":"Portage, Michigan, USA – October 31, 2025 – Stryker, a global leader in medical technologies, today announced that United Healthcare has removed language deeming ClariFix CPT® 31243 as experimental,investigational, and unproven from their Medicare Advantage policy effective immediately. This update marks a significant advancement in patient access to an evidence-based treatment for chronic rhinitis.","image":null,"imageAlt":null,"tags":["stryker:content-type/news"],"originallyPublished":"2025-10-31T13:43:54.000Z","lastPublished":"2025-11-03T13:53:56.000Z","contentID":"ENT-GSNPS-SYK-2524373_REV-0"},"anchors":[],"disclaimer":null,"forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
