"/us/en/sage/news/2023/external-urine-collection-device-JWOCN-study": {"template":"news-detail","metadata":{"title":"Sage PrimaFit External Urine Management System for the Female Anatomy helped reduce CAUTI rate 63% ","pageTitle":"Sage PrimaFit External Urine Management System for the Female Anatomy helped reduce CAUTI rate 63% ","description":"Catheter-related infections decreased from before the introduction to EUDFA and after. This is not a cause-and-effect relationship, but the trend is promising.","image":"/content/dam/stryker/sage/urine-management/images/primafit-video-thumbnail.png","imageAlt":"PrimaFit External Urine Management for the Female Anatomy photo of application","tags":["stryker:content-type/news/sage/4","stryker:content-type/news","stryker:content-type/news/sage/2"],"originallyPublished":null,"lastPublished":"2024-02-07T15:31:12.000Z","contentID":"SAGE-UM-COMM-862232_REV-0_en_us"},"anchors":[],"disclaimer":"<p>Conflict of Interest: The authors declare that funding for this study and for assistance with manuscript preparation was supplied by Sage Products, a business unit of Stryker.</p>\r\n<p>1. Beeson T, Pittman J, Davis CR, Effectiveness of an External Urinary Device for Female Anatomy and Trends in Catheter-Associated Urinary Tract Infections, Journal of Wound Ostomy Continence Nursing, 2023;50(2):137-41.&nbsp;</p>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
