"/us/en/sage/news/2023/nyc-medical-center-implementation-of-external-female-catheter-av": {"template":"news-detail","metadata":{"title":"NYC Medical Center Implementation of External Female Catheter avoids  $16M in costs over 2 years ","pageTitle":null,"description":"In 2018, the implementation of the external female urine management device was introduced as a standard of nursing care as an alternative to an indwelling urinary catheter. Data captured in 2019 and 2020 showed utilization of the external female device to be 36% and 46%, respectively.","image":"/content/dam/stryker/sage/news/2023/23-SGC-712791-June_Newsroom3.jpg","imageAlt":"23-SGC-712791-June_Newsroom3","tags":["stryker:content-type/news"],"originallyPublished":"2023-02-06T14:53:02.000Z","lastPublished":"2024-09-10T14:53:02.000Z","contentID":"SAGE-UM-COMM-712791_REV-0_en_us"},"anchors":[],"disclaimer":"<p><b>Reference: 1. </b>Tran C, et al., Addressing CAUTIs with an External Female Catheter, The American Journal of Nursing 2023;123(1):50-55.&nbsp;</p>","forms":[],"tabs":[],"cardLists":[],"missingAlt":[]},
